{
  "packet_id": "H6-T01-3",
  "claim_id": "C049",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C049.component",
    "value": "Corroborated timing alone does not establish what caused lateness.",
    "scope": "A causal-inference limit even when timing has been corroborated.",
    "provenance": {
      "refs": [
        {
          "source_id": "P031",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P031 explicitly states that corroborated timing does not itself establish the cause of lateness."
    }
  },
  "signal_basis": {
    "component_id": "C049.signal_basis",
    "value": "Credible sources with independent access converge on a timing feature, such as equipment returning after the next scheduled start.",
    "scope": "Corroboration concerns the same equipment, booking and handoff, and increases support for the specific observed feature.",
    "provenance": {
      "refs": [
        {
          "source_id": "P016",
          "role": "SUPPORT"
        },
        {
          "source_id": "P017",
          "role": "SUPPORT"
        },
        {
          "source_id": "P022",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the shared event, an illustrative timing observation, and the credibility, independence and feature-specific bounds of corroboration."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C049.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as an inferential limit; no conditional empirical relation is required."
    }
  },
  "rationale": "Independent agreement can establish confidence in when events occurred without establishing their causal contribution to lateness. Even with successful corroboration, chronology alone does not resolve competing causal explanations, so the stated limit is licensed.",
  "uncertainty": "The actual cause of lateness remains unresolved; that uncertainty is consistent with the claim.",
  "anomalies": []
}
